#include <bits/stdc++.h>
using namespace std;

long long h, Ans, l, r, can, x, m;

int main() {
    cin >> h >> x;
    l = 1;
    r = (1LL << h);

    for (long long i = 0; i < h; ++i) {
        m = (l + r) >> 1LL;

        if (!can) {
            if (x > m)
                l = m + 1LL, Ans += (1LL << (h - i)) - 1LL;
            else
                r = m, can = 1;
        } else {
            if (x <= m)
                r = m, Ans += (1LL << (h - i)) - 1LL;
            else
                l = m + 1LL, can = 0;
        }
    }

    cout << Ans + h;
    return 0;
}

